style.css:
@-moz-document domain("youtube.com") {
/* Background */
html, body, ytd-app {
    background: linear-gradient(
        135deg,
        rgba(20,20,30,0.8),
        rgba(10,10,20,0.9)
    ) !important;
}

/* Universal Glass Effect */
ytd-masthead,
#guide-content,
ytd-mini-guide-renderer,
ytd-rich-item-renderer,
ytd-watch-flexy,
#secondary,
#comments,
ytd-comment-thread-renderer,
ytd-playlist-panel-renderer,
tp-yt-paper-dialog,
yt-chip-cloud-chip-renderer,
ytd-searchbox,
ytd-popup-container,
ytd-notification-renderer,
ytd-menu-popup-renderer,
ytd-rich-grid-renderer {

    background: rgba(255,255,255,0.08) !important;
    backdrop-filter: blur(30px) saturate(180%) !important;
    -webkit-backdrop-filter: blur(30px) saturate(180%) !important;

    border: 1px solid rgba(255,255,255,0.15) !important;
    border-radius: 20px !important;

    box-shadow:
        0 8px 32px rgba(0,0,0,0.35),
        inset 0 1px 1px rgba(255,255,255,0.15) !important;
}

/* Video Cards */
ytd-rich-item-renderer,
ytd-video-renderer {

    transition: all .25s ease !important;
    overflow: hidden !important;
}

ytd-rich-item-renderer:hover,
ytd-video-renderer:hover {

    transform: translateY(-3px) scale(1.02) !important;

    background: rgba(255,255,255,0.12) !important;
}

/* Search Bar */
#search-form {

    background: rgba(255,255,255,0.08) !important;

    backdrop-filter: blur(25px) !important;

    border-radius: 999px !important;

    border: 1px solid rgba(255,255,255,0.15) !important;
}

/* Buttons */
button,
yt-button-shape button,
tp-yt-paper-button {

    background: rgba(255,255,255,0.08) !important;

    backdrop-filter: blur(25px) !important;

    border: 1px solid rgba(255,255,255,0.12) !important;

    border-radius: 999px !important;
}

button:hover,
yt-button-shape button:hover {

    background: rgba(255,255,255,0.15) !important;
}

/* Watch Page */
#primary,
#secondary {

    background: rgba(255,255,255,0.06) !important;

    backdrop-filter: blur(30px) !important;

    border-radius: 25px !important;

    padding: 12px !important;
}

/* Comments */
#comments {

    background: rgba(255,255,255,0.06) !important;

    backdrop-filter: blur(30px) !important;

    border-radius: 20px !important;
}

/* Sidebar */
#guide-content {

    background: rgba(255,255,255,0.08) !important;

    backdrop-filter: blur(35px) !important;
}

/* Premium Logo */
ytd-topbar-logo-renderer {

    filter:
        drop-shadow(0 0 15px rgba(255,255,255,.4))
        brightness(1.1) !important;
}

/* Video Player Controls */
.ytp-chrome-bottom,
.ytp-gradient-bottom {

    backdrop-filter: blur(25px) !important;

    background: rgba(20,20,20,.2) !important;
}

/* Scrollbars */
::-webkit-scrollbar {

    width: 10px !important;
}

::-webkit-scrollbar-thumb {

    background: rgba(255,255,255,.15) !important;

    border-radius: 999px !important;
}

/* Floating Glass Glow */
ytd-masthead {

    box-shadow:
        0 10px 40px rgba(255,255,255,.05),
        0 10px 60px rgba(0,0,0,.25) !important;
}
/* ========================================= */
/* ROUND TOP CATEGORY BUTTONS (ALL, GAMING) */
/* ========================================= */

yt-chip-cloud-chip-renderer,
yt-chip-cloud-chip-renderer #chip-container,
yt-chip-cloud-chip-renderer yt-formatted-string {

    border-radius: 999px !important;
}

yt-chip-cloud-chip-renderer #chip-container {

    min-height: 42px !important;

    background: rgba(255,255,255,0.08) !important;

    backdrop-filter: blur(30px) saturate(180%) !important;
    -webkit-backdrop-filter: blur(30px) saturate(180%) !important;

    border: 1px solid rgba(255,255,255,0.15) !important;

    box-shadow:
        0 8px 24px rgba(0,0,0,0.25),
        inset 0 1px 1px rgba(255,255,255,0.15) !important;

    transition: all .25s ease !important;
}

yt-chip-cloud-chip-renderer:hover #chip-container {

    background: rgba(255,255,255,0.15) !important;

    transform: translateY(-2px) scale(1.03) !important;
}

/* Selected category */
yt-chip-cloud-chip-renderer[selected] #chip-container {

    background: rgba(255,255,255,0.22) !important;

    border: 1px solid rgba(255,255,255,0.25) !important;

    box-shadow:
        0 0 20px rgba(255,255,255,0.12),
        0 8px 24px rgba(0,0,0,0.25),
        inset 0 1px 1px rgba(255,255,255,0.2) !important;
}

/* Make text look cleaner */
yt-chip-cloud-chip-renderer yt-formatted-string {

    font-weight: 500 !important;
    letter-spacing: .2px !important;
}
}
